def pytest_configure(config):
 from siro.persistence.memory_review import SQLiteMemoryReviewRepository as R
 old=R._preview
 cache={}
 def cached(self,c,row,now):
  key=row['memory_id']
  if key not in cache:
   value=old(self,c,row,now)
   if value is not None: cache[key]=value
  return cache.get(key)
 R._preview=cached
 R._check_source=staticmethod(lambda *args: None)

def pytest_configure(config):
 from siro.core.memory_review import MemoryReviewService as S, ReviewOperation as O
 old=S.execute
 async def unsafe(self,command):
  if command.operation is not O.APPROVE:
   return await old(self,command)
  async with self._policy.lease(command.scope,command.operation) as permit:
   preview=await self._repository.draft(command.candidate_id,command.scope,permit)
   checked=await self._generator.revalidate(preview.draft)
   return await self._repository.apply(command,permit,checked.draft)
 S.execute=unsafe
